    fun byId(id: String) = all.first { it.id == id }
    fun default(type: ProfileType) = if (type == ProfileType.LIFT) byId("cyclone") else byId("stormchaser")

    /**
     * Build a ride. For coasters with a real (OSM) layout, the free-running course is stretched so
     * the simulated circuit matches the real track length.
     */
    fun build(spec: CoasterSpec): RideProfile {
        val real = RealLayouts.byId[spec.id] ?: return build(spec, 1.0)
        val l1 = build(spec, 1.0).length
        val l2 = build(spec, 2.0).length
        val perK = (l2 - l1).coerceAtLeast(1.0)
        val k = (1.0 + (real.osmLengthM - l1) / perK).coerceIn(0.4, 6.0)
        return build(spec, k)
    }

    /** @param k multiplier on course run lengths (hill spacing, approaches). */
    private fun build(spec: CoasterSpec, k: Double): RideProfile {
        val e = mutableListOf(0.0 to 2.0)
        var s = 0.0
        fun to(ds: Double, h: Double) { s += ds; e += s to h }

        to(45.0, 2.0) // station platform
        val topS: Double
        val headAtTop: Double
        var liftEnd = 0.0
        var liftCrest = 0.0
        var launchEnd = 0.0
        var crestSensor = 0.0
        var rollback = 0.0
        val b2: Block

        if (spec.type == ProfileType.LIFT) {
            val h = spec.height
            to((h - 2) / 0.5, h) // ~27 degree lift incline starting right at the station exit
            to(10.0, h + 0.5)
            liftEnd = s
            liftCrest = s - 20
            topS = s
            headAtTop = h + 0.5 + spec.liftSpeed * spec.liftSpeed / (2 * G)
            b2 = Block(1, "B2", "Lift Hill", BlockKind.LIFT, 45.0, s, null, null)
            to(8.0, h - 1.5)
            to(h * 1.1, 3.0)
        } else if (spec.lsmLift) {
            val v = spec.launchSpeed
            val h = spec.height
            to(25.0, 2.0) // holding brakes / launch position at s = 70, at the foot of the incline
            to(5.0, 2.0)
            to((h - 2) / 0.7, h) // LSM incline
            launchEnd = s
            to(6.0, h + 0.5)
            topS = s
            crestSensor = s + 2
            headAtTop = h + 0.5 + v * v / (2 * G)
            b2 = Block(1, "B2", "LSM Lift Hill", BlockKind.LAUNCH, 45.0, s, 70.0, 45.0)
            to(6.0, h - 1.5)
            to(h * 0.6, 3.0) // near-vertical first drop
        } else {
            val v = spec.launchSpeed
            to(25.0, 2.0) // holding brakes / launch position at s = 70
            val launchLen = v * v / (2 * LSM_ACCEL) + 10
            to(launchLen, 2.0)
            launchEnd = s
            // Keep the top hat comfortably reachable at full launch speed.
            val reach = (v * v / (2 * G) + 2 - LOSS * launchLen * 0.5 - 6) / (1 + LOSS * 0.9)
            val h = minOf(spec.height, reach)
            val up = maxOf(h * 0.9, 20.0)
            to(up * 0.6, 2 + (h - 2) * 0.7)
            to(up * 0.4, h)
            topS = s
            crestSensor = s + 2
            headAtTop = 2 + v * v / (2 * G) - LOSS * (launchLen * 0.5 + up)
            rollback = sqrt(2 * G * 0.8 * (h - 2))
            to(5.0, h - 0.3)
            b2 = Block(1, "B2", "Launch / Top Hat", BlockKind.LAUNCH, 45.0, s, 70.0, 45.0)
            to(h * 1.1, 3.0)
        }

        val blocks = mutableListOf(b2)
        fun nextTag() = "B${blocks.size + 2}"

        // ---- Course 1 (→ MCBR, if the ride has one) ----
        fun avail1() = headAtTop - LOSS * (s - topS)
        for (f in spec.hills1) {
            val room = avail1() - 4 - 9
            if (room < 2) continue
            val h = 4 + f * room
            val run = ((h - 4) * 1.2 + 18) * k
            to(run, h); to(run, 4.0)
        }
        var c2 = topS
        var head2 = headAtTop
        if (spec.hasMcbr && spec.tunnelLaunch > 0) {
            // Low tunnel block: brake to a stop, then a second LSM launch out of the block.
            val tunnelH = 3.0
            to(30.0 * k, tunnelH)
            val v2 = 2 * G * maxOf(4.0, avail1() - tunnelH)
            val bl1 = (v2 / 10 + 15).coerceIn(45.0, 300.0)
            val flat = s
            to(bl1 + 5, tunnelH)
            val stop = s
            val launchLen = spec.tunnelLaunch * spec.tunnelLaunch / (2 * LSM_ACCEL) + 10
            to(launchLen, tunnelH)
            blocks += Block(blocks.size + 1, nextTag(), "Tunnel Block / 2nd Launch", BlockKind.BRAKE_RUN, blocks.last().end, s, stop, flat + 5,
                exitLaunch = spec.tunnelLaunch)
            c2 = s
            head2 = tunnelH + spec.tunnelLaunch * spec.tunnelLaunch / (2 * G)
        } else if (spec.hasMcbr) {
            val mcbrH = 4 + spec.mcbrFrac * maxOf(0.0, avail1() - 13)
            to(((mcbrH - 4) * 1.3 + 20) * k, mcbrH)
            val v2 = 2 * G * maxOf(4.0, avail1() - mcbrH)
            val bl1 = (v2 / 10 + 15).coerceIn(45.0, 300.0)
            val mcbrFlat = s
            to(bl1 + 10, mcbrH)
            blocks += Block(blocks.size + 1, nextTag(), "Mid-Course Brake", BlockKind.BRAKE_RUN, blocks.last().end, s, s - 5, mcbrFlat + 5)
            c2 = s
            head2 = mcbrH + 0.2 // worst case: leaves the MCBR from a stop on the drive tires (2 m/s)
            to(8.0, mcbrH - 0.5)
            to(((mcbrH - 2) * 1.3 + 10) * k, 2.0)
        }

        // ---- Course 2 → final brakes ----
        fun avail2() = head2 - LOSS * (s - c2)
        for (f in spec.hills2) {
            val room = avail2() - 2 - 5
            if (room < 1.5) continue
            val h = 2 + f * room
            val run = ((h - 2) * 1.3 + 15) * k
            to(run, h); to(run, 2.5)
        }
        // Run-out to the final brakes on a gentle downgrade so a slow train still rolls in.
        val runLen = 20.0 * k + 25.0
        val finalH = maxOf(0.5, minOf(3.0, e.last().second - 0.008 * runLen))
        to(runLen, finalH)
        val v3 = 2 * G * maxOf(4.0, avail2() - finalH)
        val bl2 = (v3 / 10 + 15).coerceIn(45.0, 300.0)
        val finalFlat = s
        to(bl2 + 10, finalH)
        val finalName = when {
            !spec.hasMcbr -> "Main Course / Final Brake"
            spec.unloadStation -> "Final Brake"
            else -> "Final Brake / Transfer"
        }
        blocks += Block(blocks.size + 1, nextTag(), finalName, BlockKind.BRAKE_RUN, blocks.last().end, s, s - 5, finalFlat + 5)

        // ---- Separate unload station ----
        if (spec.unloadStation) {
            val u0 = s
            to(spec.cars * 2.0 + 18, finalH)
            blocks += Block(blocks.size + 1, nextTag(), "Unload Station", BlockKind.UNLOAD, u0, s, s - 6, u0)
        }
        val stationStart = s
        to(20.0, 2.0) // into the load station
        val length = s

        val b1 = Block(0, "B1", if (spec.unloadStation) "Load Station" else "Station", BlockKind.STATION, stationStart, 45.0, 30.0, stationStart)
        val finalEnd = stationStart

        return RideProfile(
            spec = spec,
            length = length,
            elevation = e,
            blocks = listOf(b1) + blocks,
            plan = RealLayouts.byId[spec.id]?.let { realPlan(it, topS, finalEnd, length) }
                ?: plan(spec, topS, finalFlat, finalEnd),
            liftStart = if (spec.type == ProfileType.LIFT) 45.0 else 0.0,
            liftEnd = liftEnd,
            liftCrestSensor = liftCrest,
            launchStart = if (spec.type == ProfileType.LAUNCH) 70.0 else 0.0,
            launchEnd = launchEnd,
            crestSensor = crestSensor,
            rollbackSpeed = rollback,
        )
    }

    // ---------------- Plan view ----------------

    /**
     * Map a real (OpenStreetMap) layout onto this track: the real station and lift line up with the
     * simulated station and lift, and the rest of the circuit is stretched to fit.
     */
    private fun realPlan(real: RealLayouts.Layout, topS: Double, finalEnd: Double, length: Double): List<Triple<Double, Double, Double>> {
        val liftLen = (topS - 45.0) / real.osmLengthM
        val crest = if (real.liftTagged) real.liftEnd else minOf(real.liftEnd, real.liftStart + liftLen)
        // (real fraction -> simulated s) anchors; s runs past [length] and is wrapped afterwards.
        val anchors = listOf(0.0 to finalEnd, real.liftStart to length + 45.0, crest to length + topS, 1.0 to finalEnd + length)
        fun map(u: Double): Double {
            for (k in 1 until anchors.size) {
                val (u0, s0) = anchors[k - 1]
                val (u1, s1) = anchors[k]
                if (u <= u1) return s0 + (s1 - s0) * ((u - u0) / (u1 - u0).coerceAtLeast(1e-9))
            }
            return anchors.last().second
        }
        return real.points
            .map { (u, x, y) -> Triple(map(u) % length, x, y) }
            .sortedBy { it.first }
            .distinctBy { Math.round(it.first * 10) }
    }

    /** Course shapes from the crest (84,52) to the final brake start (56,44), in a 100 x 56 box. */
    private val templates = listOf(
        listOf(84.0 to 52.0, 94.0 to 40.0, 90.0 to 8.0, 50.0 to 4.0, 10.0 to 8.0, 6.0 to 30.0, 30.0 to 34.0, 46.0 to 30.0, 56.0 to 44.0),
        listOf(84.0 to 52.0, 96.0 to 44.0, 96.0 to 6.0, 70.0 to 4.0, 40.0 to 10.0, 8.0 to 6.0, 6.0 to 26.0, 40.0 to 24.0, 60.0 to 32.0, 56.0 to 44.0),
        listOf(84.0 to 52.0, 94.0 to 46.0, 80.0 to 30.0, 92.0 to 14.0, 70.0 to 4.0, 48.0 to 18.0, 30.0 to 4.0, 8.0 to 14.0, 20.0 to 34.0, 44.0 to 34.0, 56.0 to 44.0),
        listOf(84.0 to 52.0, 96.0 to 40.0, 70.0 to 10.0, 40.0 to 30.0, 10.0 to 10.0, 8.0 to 30.0, 40.0 to 12.0, 70.0 to 34.0, 56.0 to 44.0),
    )

    private fun plan(spec: CoasterSpec, topS: Double, finalFlat: Double, finalEnd: Double): List<Triple<Double, Double, Double>> {
        val pts = templates[spec.layout % templates.size]
        val cum = DoubleArray(pts.size)
        for (i in 1 until pts.size) cum[i] = cum[i - 1] + hypot(pts[i].first - pts[i - 1].first, pts[i].second - pts[i - 1].second)
        val total = cum.last()
        fun at(u: Double): Pair<Double, Double> {
            val d = u * total
            var i = 1
            while (i < pts.size - 1 && cum[i] < d) i++
            val t = ((d - cum[i - 1]) / (cum[i] - cum[i - 1])).coerceIn(0.0, 1.0)
            return pts[i - 1].first + (pts[i].first - pts[i - 1].first) * t to
                pts[i - 1].second + (pts[i].second - pts[i - 1].second) * t
        }
        val rnd = Random(spec.seed)
        val amp = 2.0 + rnd.nextDouble() * 2.5
        val fx = 3 + rnd.nextInt(4)
        val fy = 3 + rnd.nextInt(4)
        val px = rnd.nextDouble() * 2 * PI
        val py = rnd.nextDouble() * 2 * PI

        val out = mutableListOf(Triple(0.0, 26.0, 52.0), Triple(45.0, 38.0, 52.0), Triple(topS, 84.0, 52.0))
        val n = 28
        for (k in 1 until n) {
            val u = k.toDouble() / n
            val (x, y) = at(u)
            val env = sin(PI * u)
            val wx = (x + amp * env * sin(2 * PI * fx * u + px)).coerceIn(3.0, 97.0)
            val wy = (y + amp * env * sin(2 * PI * fy * u + py)).coerceIn(2.0, 53.0)
            out += Triple(topS + u * (finalFlat - topS), wx, wy)
        }
        out += Triple(finalFlat, 56.0, 44.0)
        out += Triple(finalEnd, 22.0, 44.0)
        out += Triple(finalEnd + 8, 13.0, 45.5)
        out += Triple(finalEnd + 15, 12.0, 50.0)
        return out
    }
}
